package com.bank.screening;

import java.util.*;
import java.util.logging.*;

public class CustomFiDemo {
    private static final Logger log = Logger.getLogger("Screening");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", 1000000), new Employee("Amit", 40000));
        ScreeningService service = new ScreeningService();

        // implement the single abstract method with a lambda
        SalaryCheck earnsMoreThan = (e, t) -> e.getSalary() > t;

        List<String> passed = service.screen(staff, earnsMoreThan, 50_000);
        log.info(() -> "Passed screening (salary > 50000): " + passed);
    }
}

// ─── File: src/main/java/com/bank/screening/SalaryCheck.java ───
@FunctionalInterface
interface SalaryCheck {
    boolean test(Employee e, double threshold);   // single abstract method
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final double salary;
    Employee(String name, double salary) { this.name = name; this.salary = salary; }
    String getName() { return name; }
    double getSalary() { return salary; }
}

// ─── Would be in service/ScreeningService.java ───
class ScreeningService {
    List<String> screen(List<Employee> staff, SalaryCheck check, double threshold) {
        return staff.stream()
            .filter(e -> check.test(e, threshold))   // use the custom interface
            .map(Employee::getName)
            .toList();
    }
}
